function escapeHtml(value){return String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
function setStatus(s,bad=false){$("dataStatus").textContent=s;$("dataStatus").className="status"+(bad?" error":"")}
function fmt(n,d=2){return Number.isFinite(n)?n.toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d}):"—"}
function dateInput(d){return d.toISOString().slice(0,10)}
function annualizationFactor(interval){return({"5m":18900,"15m":6300,"30m":3150,"60m":1575,"1d":252,"1wk":52,"1mo":12})[interval]||252}
function syncIntervalHint(){const value=$("interval").value;const copy={"5m":"5-minute bars · Yahoo only provides a limited recent window. Upload CSV for older history.","15m":"15-minute bars · Yahoo intraday coverage is limited. Upload CSV for longer tests.","30m":"30-minute bars · Yahoo intraday coverage is limited. Upload CSV for longer tests.","60m":"Hourly bars · Yahoo intraday coverage is limited. Upload CSV for longer tests.","1d":"Daily bars · 252 trading bars per year is used by default.","1wk":"Weekly bars · 52 bars per year is used by default.","1mo":"Monthly bars · 12 bars per year is used by default."};$("intervalHint").textContent=copy[value]||"Choose a bar interval. You can override the annualization factor below."}
