function renderDataSummary(){const n=bars.length,gaps=bars.slice(1).filter((b,i)=>Math.round((new Date(b.date)-new Date(bars[i].date))/86400000)>4).length,adjusted=bars.some(b=>Math.abs((b.adjustmentFactor||1)-1)>1e-8),adjustmentLabel=lastAdjustmentMode==="raw"?"Raw OHLC":adjusted?"Adjusted OHLC using adjusted-close factor":"No adjustment factor available; raw OHLC used";$("datasetCount").textContent=n+" ROWS";$("dataSummary").innerHTML="<b>"+lastSymbol+"</b> · "+sourceMeta+"<br/>Coverage: "+bars[0].date+" → "+bars[n-1].date+"<br/>Observations: "+n.toLocaleString()+" · Weekend/holiday gaps: "+gaps+" · Duplicate timestamps: none<br/>Price basis: "+adjustmentLabel+"<br/>Prices validated for positive OHLC values and consistent high/low bounds.<br/>Custom numeric columns: "+(customFeatureFields.length?customFeatureFields.map(f=>"x_"+f.key).join(", "):"none")+"<br/>Frequency: "+$("interval").selectedOptions[0].text+" (CSV frequency is inferred from timestamps)."}
function sma(a,p){return a.map((_,i)=>i+1<p?null:a.slice(i-p+1,i+1).reduce((s,x)=>s+x,0)/p)}
function ema(a,p){const out=Array(a.length).fill(null),k=2/(p+1);if(a.length<p)return out;let prev=a.slice(0,p).reduce((s,x)=>s+x,0)/p;out[p-1]=prev;for(let i=p;i<a.length;i++){prev=a[i]*k+prev*(1-k);out[i]=prev}return out}
function emaNullable(a,p){const first=a.findIndex(Number.isFinite);if(first<0)return Array(a.length).fill(null);return Array(first).fill(null).concat(ema(a.slice(first).map(Number),p))}
function rsi(a,p){const o=Array(a.length).fill(null);let gain=0,loss=0;for(let i=1;i<=p;i++){let d=a[i]-a[i-1];gain+=Math.max(d,0);loss+=Math.max(-d,0)}let ag=gain/p,al=loss/p;o[p]=al===0?100:100-100/(1+ag/al);for(let i=p+1;i<a.length;i++){let d=a[i]-a[i-1];ag=(ag*(p-1)+Math.max(d,0))/p;al=(al*(p-1)+Math.max(-d,0))/p;o[i]=al===0?100:100-100/(1+ag/al)}return o}
function rollingSum(a,p){const o=Array(a.length).fill(null);let sum=0;for(let i=0;i<a.length;i++){sum+=Number(a[i])||0;if(i>=p)sum-=Number(a[i-p])||0;if(i>=p-1)o[i]=sum}return o}
