function obv(data){const out=Array(data.length).fill(0);for(let i=1;i<data.length;i++)out[i]=out[i-1]+(data[i].close>data[i-1].close?data[i].volume:data[i].close<data[i-1].close?-data[i].volume:0);return out}
function donchian(data,p,side){return data.map((_,i)=>{if(i<p)return null;const w=data.slice(i-p,i);return side==="high"?Math.max(...w.map(x=>x.high)):Math.min(...w.map(x=>x.low))})}
