function adx(data,p){const tr=trueRange(data),plus=Array(data.length).fill(0),minus=Array(data.length).fill(0);for(let i=1;i<data.length;i++){const up=data[i].high-data[i-1].high,down=data[i-1].low-data[i].low;plus[i]=up>down&&up>0?up:0;minus[i]=down>up&&down>0?down:0}const trSum=rollingSum(tr,p),pSum=rollingSum(plus,p),mSum=rollingSum(minus,p),dx=tr.map((_,i)=>{if(!trSum[i])return null;const a=100*pSum[i]/trSum[i],b=100*mSum[i]/trSum[i];return a+b?100*Math.abs(a-b)/(a+b):0});return sma(dx.map(x=>x??0),p).map((x,i)=>i<2*p-2?null:x)}
