function moneyFlowIndex(data,p){const tp=data.map(b=>(b.high+b.low+b.close)/3),out=Array(data.length).fill(null);for(let i=p;i<data.length;i++){let positive=0,negative=0;for(let k=i-p+1;k<=i;k++){const flow=tp[k]*(data[k].volume||0);if(tp[k]>tp[k-1])positive+=flow;else if(tp[k]<tp[k-1])negative+=flow}out[i]=negative===0?100:positive===0?0:100-100/(1+positive/negative)}return out}
