function aroonSeries(data,p,side){return data.map((_,i)=>{if(i+1<p)return null;const w=data.slice(i-p+1,i+1),key=side==="up"?"high":"low";let extremum=side==="up"?-Infinity:Infinity,index=0;w.forEach((b,j)=>{if(side==="up"?b[key]>=extremum:b[key]<=extremum){extremum=b[key];index=j}});return p<=1?100:100*index/(p-1)})}
function chaikinMoneyFlow(data,p){return data.map((_,i)=>{if(i+1<p)return null;let money=0,volume=0;for(let k=i-p+1;k<=i;k++){const b=data[k],range=b.high-b.low,mult=range?((b.close-b.low)-(b.high-b.close))/range:0;money+=mult*(b.volume||0);volume+=b.volume||0}return volume?money/volume:0})}
