function keltnerSeries(data,p,mult,side){const mid=ema(data.map(b=>b.close),p),range=atr(data,p);return mid.map((x,i)=>x==null||range[i]==null?null:x+(side==="upper"?1:side==="lower"?-1:0)*mult*range[i])}
function dpoSeries(data,p){const close=data.map(b=>b.close),avg=sma(close,p),shift=Math.floor(p/2)+1;return close.map((x,i)=>i<shift||avg[i-shift]==null?null:close[i-shift]-avg[i-shift])}
