function temaSeries(a,p){const first=emaNullable(a,p),second=emaNullable(first,p),third=emaNullable(second,p);return first.map((x,i)=>x==null||second[i]==null||third[i]==null?null:3*x-3*second[i]+third[i])}
function hmaSeries(a,p){const half=wmaNullable(a,Math.max(2,Math.floor(p/2))),full=wmaNullable(a,p),diff=half.map((x,i)=>x==null||full[i]==null?null:2*x-full[i]);return wmaNullable(diff,Math.max(2,Math.floor(Math.sqrt(p))))}
function kamaSeries(a,p,fast=2,slow=30){const out=Array(a.length).fill(null),fastSC=2/(fast+1),slowSC=2/(slow+1);if(a.length<=p)return out;out[p]=a[p];for(let i=p+1;i<a.length;i++){const change=Math.abs(a[i]-a[i-p]);let volatility=0;for(let j=i-p+1;j<=i;j++)volatility+=Math.abs(a[j]-a[j-1]);const er=volatility?change/volatility:0,sc=(er*(fastSC-slowSC)+slowSC)**2;out[i]=out[i-1]+sc*(a[i]-out[i-1])}return out}
function parabolicSar(data,step=.02,maxStep=.2){const n=data.length,out=Array(n).fill(null);if(n<2)return out;let bull=data[1].close>=data[0].close,sar=bull?Math.min(data[0].low,data[1].low):Math.max(data[0].high,data[1].high),ep=bull?Math.max(data[0].high,data[1].high):Math.min(data[0].low,data[1].low),af=step;out[1]=sar;for(let i=2;i<n;i++){let next=sar+af*(ep-sar);if(bull){next=Math.min(next,data[i-1].low,data[i-2].low);if(data[i].low<next){bull=false;next=ep;ep=data[i].low;af=step}else if(data[i].high>ep){ep=data[i].high;af=Math.min(maxStep,af+step)}}else{next=Math.max(next,data[i-1].high,data[i-2].high);if(data[i].high>next){bull=true;next=ep;ep=data[i].high;af=step}else if(data[i].low<ep){ep=data[i].low;af=Math.min(maxStep,af+step)}}sar=next;out[i]=sar}return out}
function supertrendParts(data,p,mult){const n=data.length,atrLine=atr(data,p),upper=Array(n).fill(null),lower=Array(n).fill(null),direction=Array(n).fill(null),line=Array(n).fill(null);for(let i=0;i<n;i++){if(atrLine[i]==null)continue;const mid=(data[i].high+data[i].low)/2,basicUpper=mid+mult*atrLine[i],basicLower=mid-mult*atrLine[i];if(i===0||upper[i-1]==null){upper[i]=basicUpper;lower[i]=basicLower;direction[i]=1;line[i]=basicLower;continue}upper[i]=basicUpper<upper[i-1]||data[i-1].close>upper[i-1]?basicUpper:upper[i-1];lower[i]=basicLower>lower[i-1]||data[i-1].close<lower[i-1]?basicLower:lower[i-1];direction[i]=direction[i-1]===-1&&data[i].close>upper[i-1]?1:direction[i-1]===1&&data[i].close<lower[i-1]?-1:direction[i-1];line[i]=direction[i]===1?lower[i]:upper[i]}return{upper,lower,direction,line}}
