function previewStrategySignals(){
 if(!bars.length){$("signalPreview").textContent="Load historical data in the Research terminal first.";return}
 try{
  const params=readFormulaParameters(),strategy={...builderDraft,direction:$("customDirection").value,parameterValues:params.values,parameters:params.defs,indicators:readCustomIndicators()};
  if(strategy.mode==="formula"){
   const asts=buildCustomIndicatorAsts(strategy.indicators);
   strategy.entryFormula=$("entryFormula").value.trim();strategy.exitFormula=$("exitFormula").value.trim();
   strategy.shortEntryFormula=$("shortEntryFormula").value.trim();strategy.shortExitFormula=$("shortExitFormula").value.trim();
   validateFormulaIndicatorRefs(strategy.entryFormula,asts,"Long entry");validateFormulaIndicatorRefs(strategy.exitFormula,asts,"Long exit");
   if(strategy.direction==="both"){validateFormulaIndicatorRefs(strategy.shortEntryFormula,asts,"Short entry");validateFormulaIndicatorRefs(strategy.shortExitFormula,asts,"Short cover")}
  }
  const signals=calcCustomSignals(bars,strategy),counts={longEntry:signals.longEntry.filter(Boolean).length,longExit:signals.longExit.filter(Boolean).length,shortEntry:signals.shortEntry.filter(Boolean).length,shortExit:signals.shortExit.filter(Boolean).length};
  const events=[];for(let i=0;i<bars.length;i++)if(signals.longEntry[i]||signals.longExit[i]||signals.shortEntry[i]||signals.shortExit[i])events.push({bar:bars[i],signals,i});
  const recent=events.slice(-20).reverse(),cell=x=>x?'<b class="signal-mark signal-entry">YES</b>':'<span class="muted-copy">—</span>';
  const chips=[["Long entries",counts.longEntry],["Long exits",counts.longExit],["Short entries",counts.shortEntry],["Short covers",counts.shortExit]];
  $("signalPreview").innerHTML='<div class="signal-preview-summary">'+chips.map(([label,value])=>'<span class="signal-chip">'+label+': <b>'+value+'</b></span>').join("")+'<span class="signal-chip">Bars checked: <b>'+bars.length.toLocaleString()+'</b></span></div>'+(recent.length?'<div class="signal-table-wrap"><table class="signal-table"><thead><tr><th>DATE</th><th>CLOSE</th><th>LONG ENTRY</th><th>LONG EXIT</th><th>SHORT ENTRY</th><th>COVER</th></tr></thead><tbody>'+recent.map(x=>'<tr><td>'+escapeHtml(x.bar.date)+'</td><td>'+fmt(x.bar.close)+'</td><td>'+cell(x.signals.longEntry[x.i])+'</td><td>'+cell(x.signals.longExit[x.i])+'</td><td>'+cell(x.signals.shortEntry[x.i])+'</td><td>'+cell(x.signals.shortExit[x.i])+'</td></tr>').join("")+'</tbody></table></div>':'<div class="rule-empty">No signals fired on the loaded data. Check your rules, formulas, lookback periods and selected date range.</div>')+'<p class="small-note">Showing the latest '+recent.length+' signal bars. A signal uses the completed bar; the simulator fills it at the next bar open.</p>';
 }catch(error){$("signalPreview").innerHTML='<span class="negative">Could not evaluate this draft: '+escapeHtml(error.message)+'</span>'}
}
